-- The tables the routing tests use, extracted from iznik-batch/database/postgres/baseline.sql
-- by scripts/pg-test-schema.mjs. Do not edit by hand.

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS citext;

CREATE TABLE chat_messages (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  chatid bigint NOT NULL,
  userid bigint NOT NULL,
  type text DEFAULT 'Default' NOT NULL,
  reportreason text,
  refmsgid bigint,
  refchatid bigint,
  imageid bigint,
  date timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  message text,
  platform smallint DEFAULT 1 NOT NULL,
  seenbyall smallint DEFAULT 0 NOT NULL,
  mailedtoall smallint DEFAULT 0 NOT NULL,
  reviewrequired smallint DEFAULT 0 NOT NULL,
  reviewedby bigint,
  reviewrejected smallint DEFAULT 0 NOT NULL,
  spamscore integer,
  processingfailreason varchar(255),
  scheduleid bigint,
  replyexpected smallint,
  replyreceived smallint DEFAULT 0 NOT NULL,
  processingrequired smallint DEFAULT 0 NOT NULL,
  processingsuccessful smallint DEFAULT 0 NOT NULL,
  confirmrequired smallint DEFAULT 0 NOT NULL,
  deleted smallint DEFAULT 0 NOT NULL,
  norfolkmsgid bigint,
  CONSTRAINT chat_messages_type_check CHECK (type IN ('Default', 'System', 'ModMail', 'Interested', 'Promised', 'Reneged', 'ReportedUser', 'Completed', 'Image', 'Address', 'Nudge', 'Schedule', 'ScheduleUpdated', 'Reminder', 'Prompt')),
  CONSTRAINT chat_messages_reportreason_check CHECK (reportreason IN ('Spam', 'Other', 'Last', 'Force', 'Fully', 'TooMany', 'User', 'UnknownMessage', 'SameImage', 'DodgyImage', 'CountryBlocked', 'IPUsedForDifferentUsers', 'IPUsedForDifferentGroups', 'SubjectUsedForDifferentGroups', 'SpamAssassin', 'Greetings spam', 'Referenced known spammer', 'Known spam keyword', 'URL on DBL', 'BulkVolunteerMail', 'UsedOurDomain', 'WorryWord', 'Script', 'Link', 'Money', 'Email', 'Language', 'Lockdown')),
  PRIMARY KEY (id)
);

CREATE TABLE config (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  key varchar(255) NOT NULL,
  value text NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE groups (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  legacyid bigint,
  nameshort citext,
  namefull citext,
  nameabbr varchar(5),
  namealt varchar(255),
  settings text,
  type text DEFAULT 'Other' NOT NULL,
  region text,
  onyahoo smallint DEFAULT 0 NOT NULL,
  onhere smallint DEFAULT 0 NOT NULL,
  ontn smallint DEFAULT 1 NOT NULL,
  showonyahoo smallint DEFAULT 1 NOT NULL,
  lastyahoomembersync timestamptz,
  lastyahoomessagesync timestamptz,
  lat numeric(10,6),
  lng numeric(10,6),
  poly text,
  polyofficial text,
  polyindex geometry(Geometry,4326) NOT NULL,
  confirmkey varchar(32),
  publish smallint DEFAULT 1 NOT NULL,
  listable smallint DEFAULT 1 NOT NULL,
  onmap smallint DEFAULT 1 NOT NULL,
  licenserequired smallint DEFAULT 1,
  trial timestamptz DEFAULT CURRENT_TIMESTAMP,
  licensed date,
  licenseduntil date,
  membercount integer DEFAULT 0 NOT NULL,
  modcount integer DEFAULT 0 NOT NULL,
  profile bigint,
  cover bigint,
  tagline varchar(255),
  description text,
  founded date,
  lasteventsroundup timestamptz,
  lastvolunteeringroundup timestamptz,
  external varchar(255),
  contactmail varchar(80),
  welcomemail text,
  activitypercent numeric(10,2),
  fundingtarget integer DEFAULT 0 NOT NULL,
  lastmoderated timestamptz,
  lastmodactive timestamptz,
  activeownercount integer,
  activemodcount integer,
  backupownersactive integer DEFAULT 0 NOT NULL,
  backupmodsactive integer DEFAULT 0 NOT NULL,
  lastautoapprove timestamptz,
  affiliationconfirmed timestamptz,
  affiliationconfirmedby bigint,
  mentored smallint DEFAULT 0 NOT NULL,
  seekingmods smallint DEFAULT 0 NOT NULL,
  privategroup smallint DEFAULT 0 NOT NULL,
  defaultlocation bigint,
  overridemoderation text DEFAULT 'None' NOT NULL,
  altlat numeric(10,6),
  altlng numeric(10,6),
  welcomereview date,
  microvolunteering smallint DEFAULT 0 NOT NULL,
  microvolunteeringoptions jsonb,
  autofunctionoverride smallint DEFAULT 0 NOT NULL,
  postvisibility geometry(Polygon,4326),
  onlovejunk smallint DEFAULT 1 NOT NULL,
  rules jsonb,
  precovidmoderated smallint DEFAULT 0 NOT NULL,
  CONSTRAINT groups_nameshort_length CHECK (char_length(nameshort) <= 80),
  CONSTRAINT groups_namefull_length CHECK (char_length(namefull) <= 255),
  CONSTRAINT groups_region_check CHECK (region IN ('East', 'East Midlands', 'West Midlands', 'North East', 'North West', 'Northern Ireland', 'South East', 'South West', 'London', 'Wales', 'Yorkshire and the Humber', 'Scotland')),
  CONSTRAINT groups_overridemoderation_check CHECK (overridemoderation IN ('None', 'ModerateAll')),
  PRIMARY KEY (id)
);

CREATE TABLE locations (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  osm_id varchar(50),
  name citext NOT NULL,
  type text NOT NULL,
  osm_place smallint DEFAULT 0,
  geometry geometry(Geometry,4326),
  ourgeometry geometry(Geometry,4326),
  gridid bigint,
  postcodeid bigint,
  areaid bigint,
  canon varchar(255),
  popularity bigint DEFAULT 0,
  osm_amenity smallint DEFAULT 0 NOT NULL,
  osm_shop smallint DEFAULT 0 NOT NULL,
  maxdimension numeric(10,6),
  lat numeric(10,6),
  lng numeric(10,6),
  timestamp timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  newareaid bigint,
  CONSTRAINT locations_name_length CHECK (char_length(name) <= 255),
  CONSTRAINT locations_type_check CHECK (type IN ('Road', 'Polygon', 'Line', 'Point', 'Postcode')),
  PRIMARY KEY (id)
);

CREATE TABLE memberships (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  userid bigint NOT NULL,
  groupid bigint NOT NULL,
  role text DEFAULT 'Member' NOT NULL,
  collection text DEFAULT 'Approved' NOT NULL,
  configid bigint,
  added timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  settings text,
  syncdelete smallint DEFAULT 0 NOT NULL,
  heldby bigint,
  emailfrequency integer DEFAULT 24 NOT NULL,
  eventsallowed smallint DEFAULT 1,
  volunteeringallowed bigint DEFAULT 1 NOT NULL,
  rippled smallint DEFAULT 0 NOT NULL,
  implicit smallint DEFAULT 0 NOT NULL,
  added_origin text DEFAULT 'unknown' NOT NULL,
  "ourPostingStatus" text,
  reviewrequestedat timestamptz,
  reviewreason varchar(255),
  reviewedat timestamptz,
  CONSTRAINT memberships_role_check CHECK (role IN ('Member', 'Moderator', 'Owner')),
  CONSTRAINT memberships_collection_check CHECK (collection IN ('Approved', 'Pending', 'Banned')),
  CONSTRAINT memberships_added_origin_check CHECK (added_origin IN ('manual', 'posted', 'replied', 'subscribed', 'rippled', 'moderator', 'partner', 'tn_unaddressed', 'signup', 'unknown')),
  CONSTRAINT "memberships_ourPostingStatus_check" CHECK ("ourPostingStatus" IN ('MODERATED', 'DEFAULT', 'PROHIBITED', 'UNMODERATED')),
  PRIMARY KEY (id)
);

CREATE TABLE messages (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  arrival timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  date timestamptz,
  deleted timestamptz,
  heldby bigint,
  source text,
  sourceheader varchar(80),
  fromip varchar(40),
  fromcountry varchar(2),
  message text NOT NULL,
  fromuser bigint,
  envelopefrom varchar(255),
  fromname varchar(255),
  fromaddr varchar(255),
  envelopeto varchar(255),
  replyto varchar(255),
  subject varchar(255),
  suggestedsubject varchar(255),
  type text,
  messageid citext,
  tnpostid varchar(80),
  textbody text,
  htmlbody text,
  retrycount integer DEFAULT 0 NOT NULL,
  retrylastfailure timestamptz,
  spamtype text,
  spamreason varchar(255),
  lat numeric(10,6),
  lng numeric(10,6),
  locationid bigint,
  editedby bigint,
  editedat timestamptz,
  availableinitially integer DEFAULT 1 NOT NULL,
  availablenow integer DEFAULT 1 NOT NULL,
  lastroute varchar(20),
  deliverypossible smallint DEFAULT 0 NOT NULL,
  deadline date,
  CONSTRAINT messages_source_check CHECK (source IN ('Yahoo Approved', 'Yahoo Pending', 'Yahoo System', 'Platform', 'Email')),
  CONSTRAINT messages_type_check CHECK (type IN ('Offer', 'Taken', 'Wanted', 'Received', 'Admin', 'Other')),
  CONSTRAINT messages_messageid_length CHECK (char_length(messageid) <= 255),
  CONSTRAINT messages_spamtype_check CHECK (spamtype IN ('CountryBlocked', 'IPUsedForDifferentUsers', 'IPUsedForDifferentGroups', 'SubjectUsedForDifferentGroups', 'SpamAssassin', 'NotSpam', 'WorryWord', 'Greetings spam', 'Referenced known spammer', 'Known spam keyword', 'URL on DBL', 'BulkVolunteerMail', 'UsedOurDomain')),
  PRIMARY KEY (id)
);

CREATE TABLE messages_attachments (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  msgid bigint,
  archived smallint DEFAULT 0,
  data bytea,
  hash varchar(16),
  rotated smallint DEFAULT 0 NOT NULL,
  "primary" smallint DEFAULT 0 NOT NULL,
  externaluid varchar(64),
  externalurl varchar(2048),
  externalmods text,
  contenttype varchar(80) NOT NULL,
  identification text,
  PRIMARY KEY (id)
);

CREATE TABLE messages_groups (
  msgid bigint NOT NULL,
  groupid bigint NOT NULL,
  collection text,
  arrival timestamptz(6) DEFAULT CURRENT_TIMESTAMP(6) NOT NULL,
  contentcheck_checked_at timestamptz,
  contentcheck_reasons text,
  autoreposts smallint DEFAULT 0 NOT NULL,
  lastautopostwarning timestamptz,
  lastchaseup timestamptz,
  deleted smallint DEFAULT 0 NOT NULL,
  senttoyahoo smallint DEFAULT 0 NOT NULL,
  yahoopendingid varchar(20),
  yahooapprovedid varchar(20),
  yahooapprove varchar(255),
  yahooreject varchar(255),
  approvedby bigint,
  approvedat timestamptz,
  heldby bigint,
  spamtype varchar(50),
  spamreason varchar(255),
  rejectedat timestamptz,
  msgtype text,
  rippled_in smallint DEFAULT 0 NOT NULL,
  mod_messaging_allowed smallint DEFAULT 1 NOT NULL,
  needs_moderator smallint DEFAULT 0 NOT NULL,
  locked_by_home smallint DEFAULT 0 NOT NULL,
  CONSTRAINT messages_groups_collection_check CHECK (collection IN ('Incoming', 'Pending', 'Approved', 'Spam', 'QueuedYahooUser', 'Rejected', 'QueuedUser')),
  CONSTRAINT messages_groups_msgtype_check CHECK (msgtype IN ('Offer', 'Taken', 'Wanted', 'Received', 'Admin', 'Other'))
);

CREATE TABLE messages_likes (
  msgid bigint NOT NULL,
  userid bigint NOT NULL,
  type text NOT NULL,
  timestamp timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  count integer DEFAULT 1 NOT NULL,
  pageview smallint,
  source varchar(32),
  CONSTRAINT messages_likes_type_check CHECK (type IN ('Love', 'Laugh', 'View'))
);

CREATE TABLE messages_outcomes (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  timestamp timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  msgid bigint NOT NULL,
  userid bigint,
  outcome text NOT NULL,
  happiness text,
  comments text,
  reviewed smallint DEFAULT 0 NOT NULL,
  feedback smallint GENERATED ALWAYS AS ((((comments is not null) and (comments <> '') and (comments not in ('Sorry, this is no longer available.','Thanks, this has now been taken.','Thanks, I''m no longer looking for this.','Sorry, this has now been taken.','Thanks for the interest, but this has now been taken.','Thanks, these have now been taken.','Thanks, this has now been received.','Withdrawn on user unsubscribe','Auto-Expired'))))::int) STORED,
  CONSTRAINT messages_outcomes_outcome_check CHECK (outcome IN ('Taken', 'Received', 'Withdrawn', 'Repost', 'Expired', 'Partial')),
  CONSTRAINT messages_outcomes_happiness_check CHECK (happiness IN ('Happy', 'Fine', 'Unhappy')),
  PRIMARY KEY (id)
);

CREATE TABLE messages_spatial (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  msgid bigint NOT NULL,
  point geometry(Geometry,4326) NOT NULL,
  successful smallint DEFAULT 0 NOT NULL,
  promised smallint DEFAULT 0 NOT NULL,
  groupid bigint,
  msgtype text,
  arrival timestamptz,
  modified timestamptz,
  CONSTRAINT messages_spatial_msgtype_check CHECK (msgtype IN ('Offer', 'Taken', 'Wanted', 'Received', 'Admin', 'Other')),
  PRIMARY KEY (id)
);

CREATE TABLE rippling_reach (
  msgid bigint NOT NULL,
  lat double precision NOT NULL,
  lng double precision NOT NULL,
  max_cumulative_users bigint,
  arrival timestamptz,
  mode varchar(8) DEFAULT 'drive' NOT NULL,
  tick integer DEFAULT 0 NOT NULL,
  min_tick integer,
  total_ticks integer DEFAULT 0 NOT NULL,
  total_freeglers bigint DEFAULT 0 NOT NULL,
  max_drive_min real,
  density_band varchar(8),
  density_radius_miles double precision,
  max_minutes_cap double precision,
  schedule text,
  reachable_group_ids jsonb,
  next_expansion_at timestamptz,
  status text DEFAULT 'expanding' NOT NULL,
  rejected_groups jsonb,
  created_at timestamptz,
  updated_at timestamptz,
  ripple_intro_sent smallint DEFAULT 0 NOT NULL,
  outer_bound geometry(Geometry,4326) NOT NULL,
  inner_bound geometry(Geometry,4326),
  polygon_cells bytea,
  max_polygon_cells bytea,
  overflow_cells jsonb,
  has_overflow smallint GENERATED ALWAYS AS (((overflow_cells is not null))::int) STORED,
  has_max_reach smallint GENERATED ALWAYS AS (((max_polygon_cells is not null))::int) STORED,
  reach_labels bytea,
  origin_union_secs real,
  reach_labels_next bytea,
  reach_labels_next_fp bigint,
  CONSTRAINT rippling_reach_status_check CHECK (status IN ('expanding', 'stopped', 'done', 'held')),
  PRIMARY KEY (msgid)
);

CREATE TABLE rippling_reach_leaves (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  msgid bigint NOT NULL,
  leaf integer NOT NULL,
  fp bigint,
  PRIMARY KEY (id)
);

CREATE TABLE sessions (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  userid bigint,
  series bigint NOT NULL,
  token varchar(255) NOT NULL,
  date timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  lastactive timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (id)
);

CREATE TABLE transport_postcode_classification (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  postcode citext NOT NULL,
  postcode_space varchar(9),
  ru_category varchar(2),
  region_code varchar(9),
  region_name varchar(50),
  lat numeric(10,6),
  lng numeric(10,6),
  imported_at timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  last_seen timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  CONSTRAINT transport_postcode_classification_postcode_length CHECK (char_length(postcode) <= 8),
  PRIMARY KEY (id)
);

CREATE TABLE users (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "yahooUserId" varchar(20),
  firstname varchar(255),
  lastname varchar(255),
  fullname varchar(255),
  systemrole text DEFAULT 'User' NOT NULL,
  added timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  lastaccess timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  settings text,
  gotrealemail smallint DEFAULT 0 NOT NULL,
  yahooid citext,
  licenses integer DEFAULT 0 NOT NULL,
  newslettersallowed smallint DEFAULT 1 NOT NULL,
  relevantallowed smallint DEFAULT 1 NOT NULL,
  onholidaytill date,
  marketingconsent smallint DEFAULT 0 NOT NULL,
  publishconsent smallint DEFAULT 0 NOT NULL,
  lastlocation bigint,
  lastrelevantcheck timestamptz,
  lastidlechaseup timestamptz,
  bouncing smallint DEFAULT 0 NOT NULL,
  permissions text,
  invitesleft bigint DEFAULT 10,
  source varchar(40),
  chatmodstatus text DEFAULT 'Moderated' NOT NULL,
  deleted timestamptz,
  inventedname smallint DEFAULT 0 NOT NULL,
  newsfeedmodstatus text DEFAULT 'Unmoderated' NOT NULL,
  replyambit integer DEFAULT 0 NOT NULL,
  engagement text,
  trustlevel text,
  lastupdated timestamptz,
  tnuserid bigint,
  ljuserid bigint,
  forgotten timestamptz,
  covidconfirmed timestamptz,
  suspectcount bigint DEFAULT 0 NOT NULL,
  suspectdate timestamptz,
  suspectreason varchar(80),
  CONSTRAINT users_yahooid_length CHECK (char_length(yahooid) <= 40),
  CONSTRAINT users_chatmodstatus_check CHECK (chatmodstatus IN ('Moderated', 'Unmoderated', 'Fully')),
  CONSTRAINT users_newsfeedmodstatus_check CHECK (newsfeedmodstatus IN ('Unmoderated', 'Moderated', 'Suppressed', '')),
  CONSTRAINT users_engagement_check CHECK (engagement IN ('New', 'Occasional', 'Frequent', 'Obsessed', 'Inactive', 'Dormant')),
  CONSTRAINT users_trustlevel_check CHECK (trustlevel IN ('Declined', 'Excluded', 'Basic', 'Moderate', 'Advanced')),
  PRIMARY KEY (id)
);

CREATE TABLE users_approxlocs (
  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  userid bigint NOT NULL,
  lat numeric(10,6) NOT NULL,
  lng numeric(10,6) NOT NULL,
  position geometry(Geometry,4326) NOT NULL,
  timestamp timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (id)
);

